      "default": "./dist/runtime/index.js"
    },
    "./internal": {
      "types": "./dist/internal.d.ts",
      "import": "./dist/internal.js",
      "default": "./dist/internal.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "ulidx": "2.4.1"
  },
  "devDependencies": {
    "@effect/vitest": "4.0.3",
    "@types/node": "25.9.1",
    "effect": "4.0.3",
    "vitest": "5.0.4"
  },
  "peerDependencies": {
    "effect": "4.0.3"
  },
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "tsdown",
    "dev": "tsdown --watch",
    "test": "vitest --run",
    "typecheck": "tsc --noEmit && tsc --noEmit -p test/runtime/tsconfig.json && tsc --noEmit -p test/entity/tsconfig.json",
    "clean": "rm -rf dist",
    "bench:config": "node bench/config/scale.mjs",
    "bench:config:typecheck": "node bench/config/typecheck-budget.mjs"
  }
}

